"""Split text lines into word or character tokens."""
def tokenize(lines: Any, token: Any = 'word') -> object {
    if (token == 'word') {
        return [line.split() for line in lines];
    } elif (token == 'char') {
        return [`list(line) for line in lines];
    } else {
        print(('ERROR: unknown token type: ' + token));
    }
}

